        else:
            not_reviewed[i]+=1

ins=[]
for m in METRICS:
    items=[(p,q) for p,q in pair_qwk[m].items() if not math.isnan(q)]
    items.sort(key=lambda t:t[1])
    if items:
        mn,mx=items[0],items[-1]
        ins.append((m,mn,mx,mx[1]-mn[1]))
    else:
        ins.append((m,None,None,float('nan')))

# heatmap matrices
mat={m:[[1.0]*4 for _ in range(4)] for m in METRICS}
for m in METRICS:
    for i,a in enumerate(ANNOTATORS):
        for j,b in enumerate(ANNOTATORS):
            if i==j: mat[m][i][j]=1.0
            else:
                key=(a,b) if (a,b) in pair_qwk[m] else (b,a)
                mat[m][i][j]=pair_qwk[m].get(key,float('nan'))

# top disagreements
top=[]
for rid,tid,q,ann_map,_ in rows:
    dms=[];det=[]
    for m in METRICS:
        vals={a:(ann_map.get(a) or {}).get(m) for a in ANNOTATORS}
        vals={a:v for a,v in vals.items() if v is not None}
        if len(vals)>=2 and len(set(vals.values()))>1:
            M=m.title()
            dms.append(M)
            det.append(M+': '+', '.join(f'{a}={vals[a]}' for a in ANNOTATORS if a in vals))
    if dms:
        top.append((len(dms),rid,tid,', '.join(dms),q,' | '.join(det)))

top.sort(key=lambda r:(-r[0], str(r[1])))

print('TOTAL',n)
print('ANY',rows_with_any)
print('FULL',rows_full)
print('RATE',f'{(rows_with_any/n*100):.1f}%')
print('OVERALL',','.join('nan' if math.isnan(v) else f'{v:.4f}' for v in overall))
print('REVIEWED',reviewed)
print('NOT_REVIEWED',not_reviewed)
print('INS')
for m,mn,mx,g in ins:
    if mn is None:
        print(m,'NA','NA','nan')
    else:
        print(m,f'{mn[0][0]}-{mn[0][1]} {mn[1]:.3f}',f'{mx[0][0]}-{mx[0][1]} {mx[1]:.3f}',f'gap {g:.3f}')
print('TOP10')
for r in top[:10]:
    print(r[0],r[1],r[2],r[3])
print('MATRIX')
for m in METRICS:
    print(m)
    for row in mat[m]:
        print(','.join('nan' if math.isnan(v) else f'{v:.3f}' for v in row))
